import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from '../libs/toast';
import axios from 'axios';

const CreateProgram: React.FC = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    program_type: '',
    duration: '',
    genre: '',
  });
  const [loading, setLoading] = useState(false);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.title || !formData.program_type) {
      toast.error('عنوان و نوع برنامه الزامی است');
      return;
    }
    try {
      setLoading(true);
      const token = localStorage.getItem('token');
      await axios.post('/api/programs', formData, {
        headers: token ? { Authorization: `Bearer ${token}` } : undefined,
      });
      toast.success('برنامه با موفقیت ایجاد شد');
      navigate('/programs');
    } catch (error) {
      toast.error('ایجاد برنامه با خطا مواجه شد');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container p-4">
      <h1 className="mb-3">ایجاد برنامه جدید</h1>
      <form onSubmit={handleSubmit} className="card">
        <div className="card-body">
          <div className="form-group">
            <label className="form-label">عنوان</label>
            <input name="title" value={formData.title} onChange={handleChange} className="form-control" placeholder="عنوان برنامه" />
          </div>
          <div className="form-group">
            <label className="form-label">نوع برنامه</label>
            <input name="program_type" value={formData.program_type} onChange={handleChange} className="form-control" placeholder="نمایش، کنسرت، نشست و ..." />
          </div>
          <div className="form-group">
            <label className="form-label">مدت زمان</label>
            <input name="duration" value={formData.duration} onChange={handleChange} className="form-control" placeholder="مثلاً 90 دقیقه" />
          </div>
          <div className="form-group">
            <label className="form-label">ژانر</label>
            <input name="genre" value={formData.genre} onChange={handleChange} className="form-control" placeholder="ژانر برنامه" />
          </div>
          <div className="form-group">
            <label className="form-label">توضیحات</label>
            <textarea name="description" value={formData.description} onChange={handleChange} className="form-control" placeholder="توضیحات برنامه" />
          </div>
        </div>
        <div className="card-footer" style={{ display: 'flex', gap: '10px' }}>
          <button type="submit" className="btn btn-success" disabled={loading}>{loading ? 'در حال ذخیره...' : 'ذخیره'}</button>
          <button type="button" className="btn btn-light" onClick={() => navigate('/programs')}>انصراف</button>
        </div>
      </form>
    </div>
  );
};

export default CreateProgram;
